#!/bin/sh
# Assemble the patch routines and regenerate the Kotlin source that embeds them.
#
# Needs the m68k binutils (apt install binutils-m68k-linux-gnu) and xxd.
# Outputs, next to this script:
#   sync_inventory.bin                 position independent SAVE fix (both ROM versions)
#   z80_timeouts.bin / .sym            v1.2 Z80 timeouts, linked at V12_Z80_BASE
#   z80_timeouts_v11.bin / .sym        v1.1 Z80 timeouts, linked at V11_Z80_BASE
# and the generated file app/src/commonMain/kotlin/dev/legendaryredfox/mgpatch/core/PatchBlobs.kt
# (the app embeds the bytes; nothing is assembled at run time).
#
# The two link bases must equal Z80_BASE of the matching profile in RomProfiles.kt;
# the unit tests check that.
set -e
cd "$(dirname "$0")"
V12_Z80_BASE=0x1BD900
V11_Z80_BASE=0x13FF00
OUT=../app/src/commonMain/kotlin/dev/legendaryredfox/mgpatch/core/PatchBlobs.kt
T=$(mktemp -d)
trap 'rm -rf "$T"' EXIT

AS=m68k-linux-gnu-as
LD=m68k-linux-gnu-ld
OC=m68k-linux-gnu-objcopy
NM=m68k-linux-gnu-nm

$AS -m68000 -o "$T/s.o" sync_inventory.s
$OC -O binary -j .text "$T/s.o" sync_inventory.bin

link() { # src base entry out
    $AS -m68000 -o "$T/z.o" "$1"
    $LD -Ttext="$2" -e "$3" -o "$T/z.elf" "$T/z.o"
    $OC -O binary "$T/z.elf" "$4.bin"
    $NM "$T/z.elf" | awk '$2=="T"{print $3, $1}' > "$4.sym"
}
link z80_timeouts.s     $V12_Z80_BASE wait_busack z80_timeouts
link z80_timeouts_v11.s $V11_Z80_BASE wait_busack z80_timeouts_v11

hex() { xxd -p "$1" | tr -d '\n'; }
sym() { # file prefix
    while read -r name addr; do
        case "$name" in _*) continue ;; esac
        printf '    const val %s_%s = 0x%s\n' "$2" "$(echo "$name" | tr a-z A-Z)" "$addr"
    done < "$1"
}

mkdir -p "$(dirname "$OUT")"
{
    echo "// GENERATED by patches/build_patches.sh from patches/*.s. Do not edit by hand."
    echo "package dev.legendaryredfox.mgpatch.core"
    echo
    echo "/** Machine code of the patch routines (hex) and the absolute addresses of their entry points. */"
    echo "internal object PatchBlobs {"
    echo "    const val SYNC_INVENTORY = \"$(hex sync_inventory.bin)\""
    echo "    const val V12_Z80 = \"$(hex z80_timeouts.bin)\""
    sym z80_timeouts.sym V12
    echo "    const val V11_Z80 = \"$(hex z80_timeouts_v11.bin)\""
    sym z80_timeouts_v11.sym V11
    echo "}"
} > "$OUT"
echo "wrote $OUT"
